    text: 'Agents Create direct agents, persist reusable agents, run named agents, and understand configuration fields. Direct agents A direct agent builder becomes a run when execute is called. It must include env and prompt because there is no persisted agent configuration to fill missing fields. TypeScript ts import { createMesh0 } from "@mesh0/sdk"; const mesh0 = createMesh0({ apiUrl: "https://api.mesh0.run", apiKey: process.env.MESH0_API_KEY, }); const run = await mesh0 .agent() .env({ OPENAI_API_KEY: process.env.OPENAI_API_KEY!, OPENAI_BASE_URL: "https://api.openai.com/v1", OPENAI_MODEL: "gpt-5.4", }) .prompt("Audit this repository and produce a patch.") .execute(); console.log(run.id); Python py from mesh0 import Mesh0 mesh0 = Mesh0( api_url="https://api.mesh0.run", api_key="mesh0.key_xxx.secret", ) run = ( mesh0.agent() .env({ "OPENAI_API_KEY": "sk_...", "OPENAI_BASE_URL": "https://api.openai.com/v1", "OPENAI_MODEL": "gpt-5.4", }) .prompt("Audit this repository and produce a patch.") .execute() ) print(run.id) Rust rs use mesh0::Mesh0; use serde_json::json; let mesh0 = Mesh0::new("https://api.mesh0.run") .with_api_key("mesh0.key_xxx.secret"); let run = mesh0 .agent() .env(json!({ "OPENAI_API_KEY": "sk_...", "OPENAI_BASE_URL": "https://api.openai.com/v1", "OPENAI_MODEL": "gpt-5.4" })) .prompt("Audit this repository and produce a patch.") .execute()?; println!("{}", run.id); Persisted agents Persisted agents are addressed by name. A named run may provide prompt append or replacement, target, notifications, and partial config overrides. TypeScript ts const auditAgent = await mesh0 .agent() .name("audit-agent") .env({ OPENAI_API_KEY: process.env.OPENAI_API_KEY!, OPENAI_BASE_URL: "https://api.openai.com/v1", OPENAI_MODEL: "gpt-5.4", }) .prompt("Audit this repository and produce a patch.") .persist(); await mesh0.cron({ expression: "0 9 * * *", name: "daily-audit" }).workflow( mesh0 .all([ mesh0.agent(auditAgent.name).prompt({ append: "Check API changes." }), mesh0.agent(auditAgent.name).prompt({ append: "Check web changes." }), ]) .then(mesh0.agent(auditAgent.name).prompt({ append: "Summarize risks." })), ); Python py from mesh0 import Mesh0 mesh0 = Mesh0(api_url="https://api.mesh0.run", api_key="mesh0.key_xxx.secret") agent = mesh0.agent("audit-agent") mesh0.cron({"expression": "0 9 * * *", "name": "daily-audit"}).workflow( mesh0.all([ agent.prompt({"append": "Check API changes."}), agent.prompt({"append": "Check web changes."}), ]).then(agent.prompt({"append": "Summarize risks."})) ) Rust rs use mesh0::{CronOptions, Mesh0}; use serde_json::json; let mesh0 = Mesh0::new("https://api.mesh0.run") .with_api_key("mesh0.key_xxx.secret"); let agent = mesh0.named_agent("audit-agent"); mesh0 .cron(CronOptions::new("0 9 * * *").name("daily-audit")) .workflow( &mesh0 .all(vec![ agent.clone().prompt(json!({ "append": "Check API changes." })), agent.clone().prompt(json!({ "append": "Check web changes." })), ]) .then(agent.prompt(json!({ "append": "Summarize risks." }))), )?; Configuration fields Field Type Description env object OPENAI_API_KEY, OPENAI_BASE_URL, OPENAI_MODEL, plus any provider-specific variables. prompt string | { append } | { replace } Default or trigger-specific prompt text. workspace object Git source or previous run source. systemPrompt string | { append } | { replace } Base instructions merged into the runner prompt. mcpServers record Codex-compatible MCP server config. skills array Well-known or git skill references. notifications object Email or Telegram completion delivery.',
